  "dataSources": {
    "base": {
      "type": "ds.search",
      "name": "Results by framework",
      "options": {
        "query": "index=summary search_name=* aad_framework=* aad_entity=*\n| fields _time aad_framework aad_entity aad_rule\n| append [| makeresults | eval aad_framework=\"none\"]",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "alltime": {
      "type": "ds.search",
      "name": "All time",
      "options": {
        "query": "index=summary search_name=* aad_framework=* aad_entity=*\n| stats min(_time) AS first_seen BY aad_framework aad_entity\n| stats dc(aad_entity) AS all_time count(eval(first_seen >= relative_time(now(), \"-7d@d\"))) AS new BY aad_framework",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "t_artex": {
      "type": "ds.chain",
      "options": {
        "extend": "base",
        "query": "| eval h=if(aad_framework=\"artex\", 1, 0), e=if(aad_framework=\"artex\", aad_entity, null())\n| eventstats dc(e) AS sources\n| timechart span=1d sum(h) AS hits max(sources) AS sources\n| fillnull value=0 hits\n| eventstats max(sources) AS sources sum(hits) AS total_hits\n| fillnull value=0 sources total_hits"
      }
    },
    "a_artex": {
      "type": "ds.chain",
      "options": {
        "extend": "alltime",
        "query": "| search aad_framework=\"artex\"\n| append [| makeresults | eval all_time=0, new=0]\n| stats max(all_time) AS all_time max(new) AS new"
      }
    },
    "t_cyberstrikeai": {
      "type": "ds.chain",
      "options": {
        "extend": "base",
        "query": "| eval h=if(aad_framework=\"cyberstrikeai\", 1, 0), e=if(aad_framework=\"cyberstrikeai\", aad_entity, null())\n| eventstats dc(e) AS sources\n| timechart span=1d sum(h) AS hits max(sources) AS sources\n| fillnull value=0 hits\n| eventstats max(sources) AS sources sum(hits) AS total_hits\n| fillnull value=0 sources total_hits"
      }
    },
    "a_cyberstrikeai": {
      "type": "ds.chain",
      "options": {
        "extend": "alltime",
        "query": "| search aad_framework=\"cyberstrikeai\"\n| append [| makeresults | eval all_time=0, new=0]\n| stats max(all_time) AS all_time max(new) AS new"
