    "latest": {
      "type": "ds.search",
      "name": "Latest results",
      "options": {
        "query": "index=summary search_name=* aad_framework=* aad_entity=*\n| stats count AS results max(_time) AS last_seen BY aad_framework search_name aad_entity\n| sort - last_seen\n| head 200\n| eval last_seen=strftime(last_seen, \"%Y-%m-%d %H:%M\")\n| rename aad_framework AS framework search_name AS search aad_entity AS \"host or address\"",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    }
  },
